<script setup lang="ts">import { RouterLink } from 'vue-router'; import { ShoppingBag } from 'lucide-vue-next'; import type { Product } from '../stores'; import { idr } from '../api'; defineProps<{product:Product}>(); defineEmits<{add:[id:string]}>();</script>
<template><article class="product-card"><RouterLink :to="`/products/${product.slug}`" class="product-image"><img :src="product.images[0]?.imageUrl" :alt="product.name"/><span v-if="product.stock<1">Sold out</span></RouterLink><div class="product-copy"><small>{{ product.category.name }}</small><RouterLink :to="`/products/${product.slug}`">{{product.name}}</RouterLink><div><b>{{idr(product.price)}}</b><button class="add-mini" :disabled="!product.stock" @click="$emit('add',product.id)"><ShoppingBag :size="16"/></button></div></div></article></template>
